var e={"Little City: A hand-drawn city builder in your browser":`Little City: Tarayıcında elle çizilmiş bir şehir kurma oyunu`,"My towns could not be written just now. The town you are on is still saved.":`Kasabalarım şu an kaydedilemedi. Açık olan kasaban yine de kayıtlı.`,"This browser will not let the town be saved, so it lasts only until you close the page.":`Bu tarayıcı kasabanın kaydedilmesine izin vermiyor; kasaba ancak sayfayı kapatana kadar kalır.`,"Town opened. It is in My towns now too.":`Kasaba açıldı. Artık Kasabalarım'da da var.`,"Your last town could not be opened by this version of Little City. It is kept safe in My towns.":`Son kasaban Little City'nin bu sürümüyle açılamadı. Kasabalarım'da güvende duruyor.`,"This is a town someone shared with you.":`Bu kasabayı biri seninle paylaştı.`,"Keep it as mine":`Benim olsun`,"Back to my town":`Kendi kasabama dön`,"{name} (from the old address)":`{name} (eski adresten)`,"Your towns could not be moved here. They are safe at the old address: {link}.":`Kasabaların buraya taşınamadı. Eski adreste güvendeler: {link}.`,"try again":`tekrar dene`,Watch:`İzle`,"Not now":`Şimdi değil`,"Town {n}":`Kasaba {n}`,"That town is not here any more.":`O kasaba artık burada değil.`,"{reason} It is kept here; a newer Little City may open it.":`{reason} Burada saklanıyor; Little City'nin daha yeni bir sürümü onu açabilir.`,"the town is not ready yet":`kasaba henüz hazır değil`,"Raiders off the coast! Boats are coming in.":`Açıkta yağmacılar var! Tekneler geliyor.`,"Raiders off the coast!":`Açıkta yağmacılar var!`,"raiders are already here":`yağmacılar zaten burada`,"A beach day on the shore":`Kıyıda plaj günü`,"Carol singers going door to door":`Kapı kapı dolaşan şarkıcılar`,"Picnics on the grass":`Çimenlerde piknik`,"A ship is launched at the shipyard":`Tersanede bir gemi denize indiriliyor`,"A snowball fight on the square":`Meydanda kartopu savaşı`,"A harvest supper on the square":`Meydanda hasat yemeği`,"Wedding bells at the chapel":`Şapelde düğün çanları`,"Children waving a ship in":`Gelen gemiye el sallayan çocuklar`,"outside the map":`haritanın dışında`,"Level brings the ground to the height where you press: drag from there across the ground":`Düzle, toprağı bastığın yerin yüksekliğine getirir: oradan toprağın üstünde sürükle`,"some of the ground cannot move: something on it would be in the way":`toprağın bir kısmı oynatılamıyor: üstündeki bir şey engel olur`,"the ground cannot move here":`toprak burada oynatılamıyor`,Link:`Bağlantı`,Done:`Tamam`,"That file could not be read.":`O dosya okunamadı.`,"Fly (F)":`Uç (F)`,Fly:`Uç`,Land:`İn`,"Drag to look":`Bakmak için sürükle`,"Esc to land":`İnmek için Esc`,"W A S D fly · Space up · Shift down · wheel for speed":`W A S D uç · Boşluk yukarı · Shift aşağı · tekerlek hız`,"Speed ×{speed}":`Hız ×{speed}`,"Almanac: special buildings and how to get them":`Almanak: özel binalar ve onları nasıl elde edeceğin`,"Close the almanac":`Almanağı kapat`,"Special buildings":`Özel binalar`,Almanac:`Almanak`,"Special buildings and the things your town does, and how to get them":`Özel binalar, kasabanda olup bitenler ve bunları nasıl elde edeceğin`,"In your town":`Kasabanda var`,"in your town":`kasabanda var`,"{got} of {all}":`{got}/{all}`,Running:`Akıyor`,Dawn:`Şafak`,Day:`Gündüz`,Dusk:`Akşam`,Night:`Gece`,Spring:`İlkbahar`,Summer:`Yaz`,Autumn:`Sonbahar`,Winter:`Kış`,Festival:`Şenlik`,Auto:`Otomatik`,Clear:`Açık`,Cloudy:`Bulutlu`,Wind:`Rüzgâr`,Mist:`Sis`,Rain:`Yağmur`,Storm:`Fırtına`,Snow:`Kar`,"Time of day: holding dawn":`Günün saati: hep şafak`,"Time of day: holding day":`Günün saati: hep gündüz`,"Time of day: holding dusk":`Günün saati: hep akşam`,"Time of day: holding night":`Günün saati: hep gece`,"Season: holding spring":`Mevsim: hep ilkbahar`,"Season: holding summer":`Mevsim: hep yaz`,"Season: holding autumn":`Mevsim: hep sonbahar`,"Season: holding winter":`Mevsim: hep kış`,"Season: holding festival":`Mevsim: hep şenlik`,"Weather: holding clear":`Hava: hep açık`,"Weather: holding cloudy":`Hava: hep bulutlu`,"Weather: holding wind":`Hava: hep rüzgârlı`,"Weather: holding mist":`Hava: hep sisli`,"Weather: holding rain":`Hava: hep yağmurlu`,"Weather: holding storm":`Hava: hep fırtınalı`,"Weather: holding snow":`Hava: hep karlı`,"A harbour town":`Liman kasabası`,"A harbour town is growing.":`Bir liman kasabası büyüyor.`,"A marble city":`Mermer şehir`,"A marble city is growing.":`Bir mermer şehir büyüyor.`,"A castle town":`Kale kasabası`,"A castle town is growing.":`Bir kale kasabası büyüyor.`,"A market town":`Pazar kasabası`,"A market town is growing.":`Bir pazar kasabası büyüyor.`,"A river town":`Nehir kasabası`,"A river town is growing.":`Bir nehir kasabası büyüyor.`,"A farming village":`Çiftçi köyü`,"A farming village is growing.":`Bir çiftçi köyü büyüyor.`,"A hill town":`Tepe kasabası`,"A hill town is growing.":`Bir tepe kasabası büyüyor.`,"A garden town":`Bahçe kasabası`,"A garden town is growing.":`Bir bahçe kasabası büyüyor.`,"Tap − and + to make it taller or shorter":`Yükseltmek ya da alçaltmak için − ve + düğmelerine dokun`,"Scroll to make it taller or shorter":`Yükseltmek ya da alçaltmak için kaydır`,"Tap − and + to make the brush wider or narrower":`Fırçayı genişletmek ya da daraltmak için − ve + düğmelerine dokun`,"Scroll to make the brush wider or narrower":`Fırçayı genişletmek ya da daraltmak için kaydır`,"Tap − and + to make it longer or shorter":`Uzatmak ya da kısaltmak için − ve + düğmelerine dokun`,"Scroll to make it longer or shorter":`Uzatmak ya da kısaltmak için kaydır`,"Drag the land to shape it. Drag the sea to turn the view.":`Karayı sürükleyip şekillendir. Denizi sürükleyip görüşü döndür.`,"Finishing the town…":`Kasaba tamamlanıyor…`,"Finish now":`Hemen bitir`,"Time of day":`Günün saati`,Season:`Mevsim`,Weather:`Hava`,Undo:`Geri al`,"Undo (⌘Z)":`Geri al (⌘Z)`,Redo:`Yinele`,"Redo (⇧⌘Z)":`Yinele (⇧⌘Z)`,"Time, season and weather":`Saat, mevsim ve hava`,Close:`Kapat`,fly:`uç`,"whole island":`tüm ada`,undo:`geri al`,"Buy me a coffee":`Bana bir kahve ısmarla`,"Time of day: passing":`Günün saati: akıp gidiyor`,"Season: the year is turning":`Mevsim: yıl dönüyor`,"Weather: comes and goes":`Hava: gelip geçiyor`,"This town is too big for a link, so here it is as a file.":`Bu kasaba bir bağlantıya sığmayacak kadar büyük, o yüzden işte dosya olarak.`,"Link copied. Anyone who opens it gets a copy of this town.":`Bağlantı kopyalandı. Onu açan herkes bu kasabanın bir kopyasını alır.`,"Copy this link to share your town:":`Kasabanı paylaşmak için bu bağlantıyı kopyala:`,"The postcard could not be made.":`Kartpostal yapılamadı.`,"Nothing in hand: just look around. Pick a piece to build again.":`Elin boş: sadece etrafa bak. Yeniden yapmak için bir parça seç.`,"This island has no coast for a harbour.":`Bu adada liman için kıyı yok.`,"This island has no room for a forum.":`Bu adada forum için yer yok.`,"This island has no room for a castle.":`Bu adada kale için yer yok.`,"This island has no room for a market.":`Bu adada pazar için yer yok.`,"This island has no river long enough.":`Bu adada yeterince uzun bir nehir yok.`,"This island has no room for farms.":`Bu adada çiftlikler için yer yok.`,"This island has no high ground.":`Bu adada yüksek yer yok.`,"This island has no room for gardens.":`Bu adada bahçeler için yer yok.`,Menu:`Menü`,Back:`Geri`,"The town you have now stays in My towns.":`Şu anki kasaban Kasabalarım'da kalır.`,"The town you have now will be gone.":`Şu anki kasaban yok olacak.`,"Music volume":`Müzik ses düzeyi`,"Sounds volume":`Seslerin ses düzeyi`,"Sound: on":`Ses: açık`,"Sound: off":`Ses: kapalı`,Music:`Müzik`,Sounds:`Sesler`,"Rebuild: on":`Yeniden inşa: açık`,"Rebuild: off":`Yeniden inşa: kapalı`,"Raiders: on":`Yağmacılar: açık`,"Raiders: off":`Yağmacılar: kapalı`,"Town stats: on":`İstatistikler: açık`,"Town stats: off":`İstatistikler: kapalı`,"Grow a town":`Kasaba büyüt`,"My towns":`Kasabalarım`,"New island":`Yeni ada`,"Share link":`Bağlantı paylaş`,Postcard:`Kartpostal`,"Save town to a file":`Kasabayı dosyaya kaydet`,"Open a town file":`Kasaba dosyası aç`,Language:`Dil`,"On this island":`Bu adada`,"On a new island":`Yeni bir adada`,"Surprise me":`Beni şaşırt`,"What kind of town?":`Nasıl bir kasaba?`,"What kind of island?":`Nasıl bir ada?`,Lightning:`Yıldırım`,"Click a building: a little storm cloud gathers over it and a bolt of lightning sets it alight. Timber and thatch burn fast and the wind carries the fire along a row; a street, a wall or water stops it, and stone only scorches.":`Bir binaya tıkla: üstünde küçük bir fırtına bulutu toplanır ve bir yıldırım onu tutuşturur. Ahşap ve saz çabuk yanar, rüzgâr da ateşi bir sıra boyunca taşır; bir sokak, bir duvar ya da su onu durdurur, taş ise sadece kavrulur.`,Bomb:`Bomba`,"Click anywhere: a bomb drops, fizzes and goes off. What is right beside it falls to rubble, what is near loses its glass, and every bird takes off. In the sea it only splashes.":`Herhangi bir yere tıkla: bir bomba düşer, cızırdar ve patlar. Hemen yanındakiler yıkıntıya döner, yakındakilerin camları kırılır ve bütün kuşlar havalanır. Denizde sadece su sıçratır.`,Nuke:`Nükleer`,"The big one: a siren, a long whistle, a white flash, a shockwave racing out, a fireball rising into a mushroom cloud. Everything for streets around is flattened, fires start at the edge, and a crater is left in the ground. One undo puts even the ground back.":`En büyüğü: bir siren, uzun bir ıslık, beyaz bir parlama, dışarı doğru yayılan bir şok dalgası, yükselip mantar buluta dönüşen bir ateş topu. Çevredeki sokaklarda her şey yerle bir olur, kenarlarda yangınlar çıkar ve toprakta bir krater kalır. Tek bir geri al, toprağı bile eski haline getirir.`,Raid:`Baskın`,"Click near a shore: a longship with a striped sail and a dragon at its prow comes in off the nearest coast, or a little fleet of rowing boats rows in, each to its own landing. The raiders storm ashore roaring, set the thatch alight, kick in doors and carry off sacks, chests and a pig, then sail away with the town in flames. Sink their ship with a bomb or a bolt of lightning and they are stranded: the town chases them into the sea. Undo puts it all back.":`Bir kıyının yakınına tıkla: en yakın kıyının açığından çizgili yelkenli, pruvasında ejderha olan uzun bir gemi gelir ya da küçük bir kayık filosu, her biri kendi iniş yerine kürek çekerek yanaşır. Yağmacılar kükreyerek karaya hücum eder, saz çatıları tutuşturur, kapıları tekmeleyip kırar, çuvalları, sandıkları ve bir domuzu alıp götürür, sonra kasabayı alevler içinde bırakıp yelken açar. Gemilerini bir bomba ya da bir yıldırımla batırırsan mahsur kalırlar: kasaba onları denize kadar kovalar. Geri al her şeyi eski haline getirir.`,Mallet:`Tokmak`,"Click a building to knock it a stage worse: cracked, then half-wrecked, then a heap of its own bricks.":`Bir binaya tıklayıp onu bir aşama daha kötü hale getir: önce çatlak, sonra yarı yıkık, sonra kendi tuğlalarından bir yığın.`,Hand:`El`,"Press on anybody out in the town, a dog, a cat, a hen, a sheep, a soldier, the knight or his horse, a little boat or a big ship: up it comes, kicking. Drag it over the roofs and let go to drop it, or flick to throw it across the island. People land, see stars, get up and carry on; whoever they hit goes over too. A ship dropped on the land lies there until it is refloated. Press on a building and it wobbles on its foundations until you let go.":`Kasabada dışarıdaki birine bas, bir köpeğe, bir kediye, bir tavuğa, bir koyuna, bir askere, şövalyeye ya da atına, küçük bir tekneye ya da büyük bir gemiye: tepinerek havaya kalkar. Çatıların üstünden sürükle ve düşürmek için bırak, ya da adanın öbür yanına fırlatmak için hızla savur. İnsanlar yere düşer, gözlerinin önünde yıldızlar uçuşur, kalkıp yollarına devam ederler; çarptıkları kişi de devrilir. Karaya düşürülen bir gemi yeniden yüzdürülene kadar orada yatar. Bir binaya basarsan sen bırakana kadar temelinin üstünde sallanır.`,UFO:`UFO`,"Click anywhere: a flying saucer swoops in, hovers over somebody out of doors near where you clicked, and beams them up, kicking and shouting for help. Half a minute later it brings them back somewhere else in town, a little dizzy. With nobody about, it searches the empty streets with its beam and flies off.":`Herhangi bir yere tıkla: bir uçan daire süzülerek gelir, tıkladığın yerin yakınında dışarıda olan birinin üstünde asılı durur ve onu ışınla yukarı çeker; o da tepinip imdat diye bağırır. Yarım dakika sonra onu kasabada başka bir yere geri getirir, başı biraz dönmüş halde. Ortalıkta kimse yoksa ışınıyla boş sokakları arar ve uçup gider.`,Mend:`Onar`,"Click something damaged: scaffolding goes up, and each click mends a stage until it is exactly as you built it. Shift-click mends it at once.":`Hasarlı bir şeye tıkla: yapı iskelesi kurulur ve her tıklama bir aşama onarır, ta ki tam senin yaptığın gibi olana kadar. Shift+tıklama bir anda onarır.`,Mischief:`Yaramazlık`,"Only your clicks start anything, and undo puts it all back.":`Hiçbir şey sen tıklamadan başlamaz, geri al da her şeyi eski haline getirir.`,"Mending a stage at a time; Shift-click mends it at once.":`Her seferinde bir aşama onarılıyor; Shift+tıklama bir anda onarır.`,"Undo puts it all back.":`Geri al her şeyi eski haline getirir.`,"click something that needs mending":`onarılması gereken bir şeye tıkla`,"click a building or a boat":`bir binaya ya da tekneye tıkla`,"click a building":`bir binaya tıkla`,"that won't catch":`o tutuşmaz`,"there is nothing left to knock down":`yıkılacak bir şey kalmadı`,"that is not damaged":`o hasarlı değil`,"Decides for itself what to be":`Ne olacağına kendisi karar verir`,House:`Ev`,Tower:`Kule`,Light:`Fener`,Lighthouse:`Deniz feneri`,Arch:`Kemer`,"Arch or bridge":`Kemer ya da köprü`,Dock:`İskele`,"Dock, on the water":`İskele, suyun üstünde`,Marble:`Mermer`,"Marble block":`Mermer blok`,Pillar:`Sütun`,Stairs:`Merdiven`,Mill:`Değirmen`,Windmill:`Yel değirmeni`,Path:`Yol`,Plaza:`Meydan`,Field:`Saha`,"Playing field: its shape makes the court, and people come to play":`Oyun sahası: şekli hangi saha olacağını belirler, insanlar da oynamaya gelir`,Fence:`Çit`,"Fence: the middle of a square, or along its edge":`Çit: bir karenin ortasına ya da kenarı boyunca`,Wall:`Duvar`,"Low wall: the middle of a square, or along its edge":`Alçak duvar: bir karenin ortasına ya da kenarı boyunca`,Stall:`Tezgâh`,"Market stall":`Pazar tezgâhı`,Tree:`Ağaç`,Garden:`Bahçe`,Fountain:`Çeşme`,Raise:`Yükselt`,"Raise the ground a level (Shift-drag to paint; scroll for a wider brush)":`Toprağı bir seviye yükselt (boyamak için Shift ile sürükle; daha geniş fırça için kaydır)`,Dig:`Kaz`,"Dig the ground down a level; at the bottom it fills with water":`Toprağı bir seviye aşağı kaz; en dipte su dolar`,Level:`Düzle`,"Bring the ground to one height: click, or Shift-drag from the height you want":`Toprağı tek bir yüksekliğe getir: tıkla ya da istediğin yükseklikten Shift ile sürükle`,Change:`Değiştir`,"Change what a block is, or turn stairs":`Bir bloğun ne olduğunu değiştir ya da merdiveni döndür`,Paint:`Boya`,"Recolour a block":`Bir bloğu yeniden boya`,Erase:`Sil`,"Remove a piece":`Bir parçayı kaldır`,"Strike a building with lightning":`Bir binaya yıldırım düşür`,"Drop a bomb":`Bomba at`,"The big one: a mushroom cloud and a crater":`En büyüğü: mantar bulutu ve krater`,"Call raiders: a longship comes in off the nearest coast":`Yağmacıları çağır: en yakın kıyının açığından uzun bir gemi gelir`,"Knock a building down a stage":`Bir binayı bir aşama yık`,"Mend a building a stage (Shift: all at once)":`Bir binayı bir aşama onar (Shift: hepsini birden)`,"Call a flying saucer: it beams up somebody near where you click, and brings them back":`Uçan daire çağır: tıkladığın yerin yakınındaki birini ışınla yukarı çeker, sonra geri getirir`,"Pick up a person, an animal or a boat and throw it: press on it, drag, let go":`Bir insanı, hayvanı ya da tekneyi kaldırıp fırlat: üstüne bas, sürükle, bırak`,Build:`Yapı`,Ground:`Zemin`,Nature:`Doğa`,Tools:`Araçlar`,"{label}:":`{label}:`,Residents:`Sakinler`,Happiness:`Mutluluk`,"of 100":`(100 üzerinden)`,Shorter:`Kısalt`,Longer:`Uzat`,"Length: scroll over the island, or press − and +":`Uzunluk: adanın üstünde kaydır ya da − ve + düğmelerine bas`,Length:`Uzunluk`,"Brush {n}":`Fırça {n}`,"Length {n}":`Uzunluk {n}`,Brush:`Fırça`,"Brush: scroll over the island, or press − and +":`Fırça: adanın üstünde kaydır ya da − ve + düğmelerine bas`,Narrower:`Daralt`,Wider:`Genişlet`,Random:`Rastgele`,"House style":`Ev stili`,"Random: every house different":`Rastgele: her ev farklı`,"{style}: {hint}":`{style}: {hint}`,"House style: {style}":`Ev stili: {style}`,"just now":`az önce`,"{n} minutes ago":{one:`{n} dakika önce`,other:`{n} dakika önce`},"{n} hours ago":{one:`{n} saat önce`,other:`{n} saat önce`},yesterday:`dün`,"{n} days ago":{one:`{n} gün önce`,other:`{n} gün önce`},"Every town you make is kept here, in this browser.":`Yaptığın her kasaba burada, bu tarayıcıda saklanır.`,"Open {name}":`Aç: {name}`,"Town name":`Kasaba adı`,"Save to a file":`Dosyaya kaydet`,Delete:`Sil`,"Here now":`Şu an burada`,"Delete {name}?":`{name} silinsin mi?`,"It will be gone for good.":`Temelli silinecek.`,"That town could not be deleted.":`O kasaba silinemedi.`,"Keep it":`Kalsın`,"Fetching your towns…":`Kasabaların getiriliyor…`,"{hint} ({key})":`{hint} ({key})`,Drawers:`Çekmeceler`,Colour:`Renk`,"Pieces and tools":`Parçalar ve araçlar`,"House: {style}":`Ev: {style}`,"{what}. Hover for styles":`{what}. Stiller için üstüne gel`,"Colour: auto (matches what you build on)":`Renk: otomatik (üstüne yaptığın şeye uyar)`,"Colour: auto":`Renk: otomatik`,"Colour {n}":`Renk {n}`,"Auto: match what you build on":`Otomatik: üstüne yaptığın şeye uy`,"Auto colour":`Otomatik renk`,"Start empty":`Boş başla`,"A town to start you off":`Başlaman için bir kasaba`,Skip:`Geç`,"Finishing…":`Tamamlanıyor…`,"Welcome to Little City":`Little City'ye hoş geldin`,"Here is a town to start you off. Build on it, change it, or begin with an empty island.":`İşte başlaman için bir kasaba. Üstüne yap, onu değiştir ya da boş bir adayla başla.`,"Empty island instead":`Onun yerine boş ada`,"It’s yours. Tap to build!":`Artık senin. Yapmak için dokun!`,"the outer five columns of the map stay sea":`haritanın kenarındaki beş sıra deniz olarak kalır`,"this is water already":`burası zaten su`,"the land can rise no higher":`kara daha fazla yükselemez`,"a dock or a bridge stands on this water":`bu suyun üstünde bir iskele ya da köprü var`,"it would push something past the top of the world":`bir şeyi dünyanın tavanından dışarı iterdi`,"something above is in the way":`yukarıdaki bir şey engel oluyor`,"something beside it is in the way":`yanındaki bir şey engel oluyor`,"a dock stays on the water":`iskele suyun üstünde kalır`,"that edit could not be read":`o değişiklik okunamadı`,"no ground to shape":`şekillendirilecek toprak yok`,"This is not a Little City town.":`Bu bir Little City kasabası değil.`,"This town link is damaged or incomplete.":`Bu kasaba bağlantısı bozuk ya da eksik.`,"This town was made by a different version of Little City.":`Bu kasaba, Little City'nin başka bir sürümüyle yapılmış.`,"There is no town in this link.":`Bu bağlantıda kasaba yok.`,"a dock goes on open water, at sea level":`iskele açık suya, deniz seviyesine konur`,"nothing can be built on a {kind}":`{kind} parçasının üstüne bir şey yapılamaz`,"a {kind} needs firm ground or the top of a solid block":`{kind} parçası sağlam bir yere ya da dolu bir bloğun üstüne konmalı`,"unknown piece":`bilinmeyen parça`,"unknown colour":`bilinmeyen renk`,"unknown rotation":`bilinmeyen dönüş`,"unknown house style":`bilinmeyen ev stili`,"inside the ground":`toprağın içinde`,"something is already there":`orada zaten bir şey var`,"unknown floor":`bilinmeyen zemin`,"floors cannot go on water":`zemin suya konamaz`,"a floor needs firm ground or the top of a solid block":`zemin sağlam bir yere ya da dolu bir bloğun üstüne konmalı`,"a floor cannot share a cell with a {kind}":`zemin, {kind} parçasıyla aynı kareye konamaz`,"there is already a {kind} there":`orada zaten bir {kind} parçası var`,"unknown edge piece":`bilinmeyen kenar parçası`,"a {kind} edge needs open, firm ground on at least one side":`{kind} kenarının en az bir yanında açık, sağlam bir yer olmalı`,"nothing there":`orada bir şey yok`,"a {kind} cannot change into a {into}":`{kind} parçası {into} parçasına dönüştürülemez`,"it is already a {kind}":`bu zaten bir {kind} parçası`,"only stairs turn":`sadece merdiven döner`,"unknown damage":`bilinmeyen hasar`,"it is not damaged":`hasarlı değil`,"unknown edit":`bilinmeyen değişiklik`,"A hand-drawn town diorama builder, free in your browser. Place a few blocks, watch them turn into a town, then watch it come to life.":`Elle çizilmiş bir kasaba dioraması kurma oyunu, tarayıcında ücretsiz. Birkaç blok koy, kasabaya dönüşmelerini izle, sonra kasabanın canlanmasını seyret.`,"a hand-drawn town diorama builder":`elle çizilmiş bir kasaba dioraması kurma oyunu`,"A hand-drawn island town with a castle, a harbour, a chapel and a lighthouse.":`Kalesi, limanı, şapeli ve deniz feneriyle elle çizilmiş bir ada kasabası.`,About:`Hakkında`,"Play free":`Ücretsiz oyna`,"<strong>Little City</strong> is a hand-drawn town diorama builder by Derek Yao. Free, in your browser, on a computer or a phone.":`<strong>Little City</strong>, Derek Yao'nun elle çizilmiş kasaba dioraması kurma oyunu. Ücretsiz, tarayıcında, bilgisayarda ya da telefonda.`,"Play now":`Hemen oyna`,"About the game":`Oyun hakkında`,"The almanac":`Almanak`,"Little City trailer: a hand-drawn town diorama builder":`Little City fragmanı: elle çizilmiş bir kasaba dioraması kurma oyunu`,"A drone flies in from the sea over a hand-drawn island town in Little City: under the washing lines, through the square where a wedding is on, and out over the quay. Little City is a hand-drawn town diorama builder by Derek Yao.":`Bir drone denizden gelip Little City'de elle çizilmiş bir ada kasabasının üstünden uçuyor: çamaşır iplerinin altından, düğün olan meydandan geçip rıhtımın üstünden açılıyor. Little City, Derek Yao'nun elle çizilmiş kasaba dioraması kurma oyunu.`,"{name} in Little City":`Little City'de {name}`,"Who made Little City?":`Little City'yi kim yaptı?`,"Is it free?":`Ücretsiz mi?`,"Yes. It runs in your browser: nothing to download, no account.":`Evet. Tarayıcında çalışır: indirecek bir şey yok, hesap yok.`,"Does it work on a phone?":`Telefonda çalışıyor mu?`,"Yes, on iPhone, iPad and Android as well as on a computer.":`Evet; bilgisayarın yanı sıra iPhone, iPad ve Android'de de çalışır.`,"Does my town save?":`Kasabam kaydediliyor mu?`,"Yes, by itself, in your browser. You can also share a town as a link, or save it as a postcard.":`Evet, kendiliğinden, tarayıcında. Bir kasabayı bağlantı olarak paylaşabilir ya da kartpostal olarak kaydedebilirsin de.`,"A tiny, hand-drawn town diorama. Something like a snow globe you build yourself.":`Minicik, elle çizilmiş bir kasaba dioraması. Kendi yaptığın bir kar küresi gibi bir şey.`,Play:`Oyna`,"Little City trailer":`Little City fragmanı`,"A hand-drawn island town in Little City, with a castle, a harbour, a chapel and a lighthouse.":`Little City'de kalesi, limanı, şapeli ve deniz feneriyle elle çizilmiş bir ada kasabası.`,"A drone flight over a town grown in the game.":`Oyunda büyütülmüş bir kasabanın üstünde drone uçuşu.`,"Place a few blocks and they turn into a town. What each one becomes depends on where you put it. A house beside a tall tower becomes a chapel. Four blocks stacked by the sea become a lighthouse. A path becomes a street, with lamps and benches along it.":`Birkaç blok koy, kasabaya dönüşsünler. Her birinin ne olacağı nereye koyduğuna bağlı. Yüksek bir kulenin yanındaki ev şapel olur. Deniz kenarında üst üste dört blok deniz feneri olur. Bir yol, kenarında lambalar ve banklarla bir sokağa dönüşür.`,"Then people move in. The miller carries flour down to the bakery, and the baker takes the bread to the stall on the square. Boats go out in the morning and come back with fish. Washing goes up on the lines. Some days there's a market. Sometimes there's a wedding.":`Sonra insanlar taşınır. Değirmenci unu fırına taşır, fırıncı da ekmeği meydandaki tezgâha götürür. Tekneler sabah açılır ve balıkla döner. Çamaşırlar iplere asılır. Bazı günler pazar kurulur. Bazen bir düğün olur.`,"The seasons turn. It snows. The lamps come on at dusk.":`Mevsimler döner. Kar yağar. Akşam lambalar yanar.`,"You can also skip the building: grow a whole town on a new island (a harbour town, a castle town, a farming village) and just watch it.":`İstersen yapmayı atlayabilirsin de: yeni bir adada koca bir kasaba büyüt (bir liman kasabası, bir kale kasabası, bir çiftçi köyü) ve sadece izle.`,'There are over 80 things to find. <a href="{guide}">The almanac</a> has all of them.':`Bulunacak 80'den fazla şey var. Hepsi <a href="{guide}">almanakta</a>.`,"A few questions":`Birkaç soru`,"Play Little City":`Little City'yi oyna`,"About Little City: a tiny, hand-drawn town diorama by Derek Yao":`Little City hakkında: Derek Yao'dan minicik, elle çizilmiş bir kasaba dioraması`,"The Little City almanac":`Little City almanağı`,"You never pick a building from a menu in Little City. You put blocks down and the town decides what they become. Here are all {n} special buildings and events, and how to get each one.":`Little City'de hiçbir binayı menüden seçmezsin. Blokları koyarsın, ne olacaklarına kasaba karar verir. İşte tüm {n} özel bina ve olay, her birini nasıl elde edeceğinle birlikte.`,"Play Little City free":`Little City'yi ücretsiz oyna`,"Little City almanac":`Little City bina almanağı`,"Little City almanac: all {n} special buildings and how to get them":`Little City almanağı: tüm {n} özel bina ve nasıl elde edilecekleri`,"How to get every special building in Little City: the chapel, the lighthouse, the keep, the watermill, market day, a wedding and the rest.":`Little City'de her özel bina nasıl yapılır: şapel, deniz feneri, iç kale, su değirmeni, pazar kurulan gün, düğün ve geri kalanı.`,"{name} is one of the things a town does by itself in Little City, a hand-drawn town diorama builder. Nobody schedules it: build the right places and it happens on its own.":`{name}, elle çizilmiş bir kasaba dioraması kurma oyunu olan Little City'de kasabanın kendiliğinden yaptığı şeylerden biri. Kimse planlamaz: doğru yerleri yap, kendi kendine olur.`,"In Little City you never choose a building from a menu. Put the blocks down like this and the town does the rest.":`Little City'de hiçbir binayı menüden seçmezsin. Blokları böyle koy, gerisini kasaba halleder.`,"{name} in Little City, drawn in ink and pencil":`Little City'de {name}, mürekkep ve kurşun kalemle çizilmiş`,"How to get it:":`Nasıl elde edilir:`,"Try it, free in your browser":`Dene, tarayıcında ücretsiz`,"More in {group}":`Daha fazlası: {group}`,"All {n} buildings and events":`Tüm {n} bina ve olay`,"About Little City":`Little City hakkında`,"{name}: how to make it happen | Little City almanac":`{name}: nasıl gerçekleşir | Little City almanağı`,"{name}: how to build it | Little City almanac":`{name}: nasıl yapılır | Little City almanağı`,"{how} Little City is a hand-drawn town diorama builder, free in your browser.":`{how} Little City, tarayıcında ücretsiz, elle çizilmiş bir kasaba dioraması kurma oyunu.`,"Little City: a hand-drawn city builder in your browser":`Little City: tarayıcında elle çizilmiş bir şehir kurma oyunu`,"A house beside a tall tower becomes a chapel. Four blocks stacked by the sea become a lighthouse. Then people move in: the miller carries flour to the bakery, boats go out for fish, and some days there's a market or a wedding on the square. The seasons turn and the lamps come on at dusk.":`Yüksek bir kulenin yanındaki ev şapel olur. Deniz kenarında üst üste dört blok deniz feneri olur. Sonra insanlar taşınır: değirmenci fırına un taşır, tekneler balığa çıkar, bazı günler meydanda pazar kurulur ya da düğün olur. Mevsimler döner, akşam lambalar yanar.`,"Or grow a whole town on a new island, a harbour town, a castle town or a farming village, and just watch it.":`Ya da yeni bir adada koca bir kasaba büyüt (bir liman kasabası, bir kale kasabası ya da bir çiftçi köyü) ve sadece izle.`,"Works on computers, iPhone, iPad and Android. Made by Derek Yao.":`Bilgisayarda, iPhone'da, iPad'de ve Android'de çalışır. Yapımcısı Derek Yao.`,"The almanac: every special building and how to get it":`Almanak: her özel bina ve nasıl elde edilir`,"Little City: your town, drawn in ink and pencil":`Little City: kasaban, mürekkep ve kurşun kalemle çizilmiş`,"The Auto block":`Otomatik blok`,Houses:`Evler`,Towers:`Kuleler`,Stone:`Taş`,Bridges:`Köprüler`,Waterfront:`Kıyı`,Green:`Yeşil`,Town:`Kasaba`,"Playing fields":`Oyun sahaları`,"Big days":`Büyük günler`,"Through the seasons":`Mevsimler boyunca`,"By the water":`Su kenarında`,"Every day":`Her gün`,"Evening and night":`Akşam ve gece`,"After mischief":`Yaramazlıktan sonra`,"The Auto block picks what to be from where you put it. On water it is a dock; across a gap of up to six, an arch; three stacked, a tower; four stacked near the sea, a lighthouse; anything else, a house.":`Otomatik blok ne olacağını koyduğun yere göre seçer. Suyun üstünde iskele olur; altıya kadar bir boşluğun üstünde kemer; üst üste üç tane, kule; denize yakın üst üste dört tane, deniz feneri; geri kalan her yerde ev.`,Chapel:`Şapel`,"Put a house two or more blocks long beside a tower three or more blocks tall.":`En az üç blok yüksekliğinde bir kulenin yanına en az iki blok uzunluğunda bir ev koy.`,Shop:`Dükkân`,"Open a house straight onto a plaza, or onto a path close by a plaza if the house is two or more storeys tall.":`Bir evin kapısını doğrudan bir meydana aç; ev en az iki katlıysa meydana yakın bir yola da açabilirsin.`,Inn:`Han`,"Build a house of six or more blocks, two or more storeys tall, where travellers arrive: on a square (a plaza three by three or more), or by the end of a bridge. Each such place has one inn.":`Yolcuların geldiği yere en az altı bloklu, en az iki katlı bir ev yap: bir meydana (en az üçe üç bir meydan) ya da bir köprünün ucuna. Böyle her yerde tek bir han olur.`,"Town hall":`Belediye binası`,"Build a big house covering eight or more squares of ground, opening onto a plaza at least three squares by three.":`En az sekiz karelik yer kaplayan büyük bir ev yap; kapısı en az üçe üç karelik bir meydana açılsın.`,Manor:`Konak`,"Build a house two or more storeys tall that covers ten or more squares of ground, or holds sixteen or more blocks in all.":`En az iki katlı, en az on karelik yer kaplayan ya da toplam en az on altı bloktan oluşan bir ev yap.`,Barn:`Ambar`,"Build a long one-storey house of six or more squares beside a garden or field of six or more, away from paths, plazas and squares; with a house beside it, it is a farmstead.":`En az altı karelik bir bahçenin ya da sahanın yanına, yollardan ve meydanlardan uzakta, en az altı karelik uzun, tek katlı bir ev yap; yanında bir ev varsa çiftlik olur.`,Smithy:`Demirhane`,"Put a one-storey house of one to three squares against a tower one or two blocks tall: the tower is its smoking forge chimney, and the hearth glows at dusk.":`Bir ya da iki blok yüksekliğinde bir kulenin dibine bir ila üç karelik, tek katlı bir ev koy: kule onun tüten ocak bacası olur ve akşam ocak kızıl kızıl parlar.`,Schoolhouse:`Okul`,"In a town of ten or more houses, give a one-storey house on a path a fenced yard beside it: the biggest such yard is the school’s, with a bell on the roof and hopscotch in the yard.":`En az on evli bir kasabada, yol kenarındaki tek katlı bir evin yanına çitle çevrili bir avlu yap: böyle avluların en büyüğü okulun olur; çatıda bir çan, avluda seksek çıkar.`,Townhouse:`Şehir evi`,"Stack a house three or more storeys tall on a single square.":`Tek bir kareye üst üste dizerek en az üç katlı bir ev yap.`,"Row house":`Sıra ev`,"Squeeze a small house, one or two squares of ground, between two houses of other colours on opposite sides.":`Bir ya da iki karelik küçük bir evi, karşılıklı iki yanındaki başka renkte iki evin arasına sıkıştır.`,"Stilt house":`Kazıklı ev`,"Build a house out over the water, standing on docks.":`Suyun üstüne, iskelelerin üzerinde duran bir ev yap.`,Boathouse:`Kayıkhane`,"Build a small house on the shore (one storey on four squares of ground or fewer, or two storeys on two or fewer), with a wall looking straight out onto the sea.":`Kıyıya küçük bir ev yap (en fazla dört karede tek kat ya da en fazla iki karede iki kat); bir duvarı doğrudan denize baksın.`,Watermill:`Su değirmeni`,"Build a house of two or more blocks on a river bank, a wall looking straight out onto the river: its wheel turns in the stream. One mill to a stretch of river.":`Bir nehir kıyısına en az iki bloklu bir ev yap, bir duvarı doğrudan nehre baksın: çarkı akıntıda döner. Nehrin her bölümüne bir değirmen.`,"Cliff house":`Uçurum evi`,"Build a house right against a cliff that rises two or more blocks above its floor.":`Tabanından en az iki blok yükselen bir uçurumun hemen dibine bir ev yap.`,Greenhouse:`Sera`,"Put a one-storey house, one or two blocks long, with garden on three or more sides of it.":`Bir ya da iki blok uzunluğunda, tek katlı bir ev koy; en az üç yanı bahçe olsun.`,"Mill house":`Değirmenci evi`,"Put a house right beside a windmill.":`Bir yel değirmeninin hemen yanına bir ev koy.`,"Keeper's cottage":`Fener bekçisinin evi`,"Put a house right beside a lighthouse.":`Bir deniz fenerinin hemen yanına bir ev koy.`,"Lookout cottage":`Gözcü kulübesi`,"Build a lone house on the highest ground of the island, with nothing else built within three squares.":`Adanın en yüksek yerine yalnız bir ev yap; üç kare içinde başka hiçbir şey olmasın.`,Steeple:`Şapel kulesi`,"A tower three or more blocks tall beside a house two or more blocks long becomes its steeple.":`En az iki blok uzunluğunda bir evin yanındaki, en az üç blok yüksekliğinde bir kule o evin şapel kulesi olur.`,"Clock tower":`Saat kulesi`,"Build a tower four or more blocks tall within two squares of a plaza at least three squares by three.":`En az üçe üç karelik bir meydana en fazla iki kare uzaklıkta, en az dört blok yüksekliğinde bir kule yap.`,"Castle turret":`Kale burcu`,"Build a tower with marble or walls against two or more of its sides.":`En az iki yanına mermer ya da duvar dayalı bir kule yap.`,Campanile:`Çan kulesi`,"Build the tallest tower in town, six or more blocks tall.":`Kasabanın en yüksek kulesini yap, en az altı blok yüksekliğinde.`,Observatory:`Gözlemevi`,"Build a tower four or more blocks tall on the highest hilltop, more than four squares from any water.":`En yüksek tepenin üstüne, herhangi bir sudan dört kareden fazla uzakta, en az dört blok yüksekliğinde bir kule yap.`,Dovecote:`Güvercinlik`,"Build a tower exactly three blocks tall with garden within two squares of it.":`Tam üç blok yüksekliğinde bir kule yap; iki kare yakınında bahçe olsun.`,"Stack the Light piece, or four or more Auto blocks, near the sea. Far inland (six squares or more from water) the Light is a folly tower.":`Denize yakın bir yere Fener parçasını ya da en az dört Otomatik bloğu üst üste koy. İç kesimlerde (sudan en az altı kare uzakta) Fener bir süs kulesi olur.`,"Folly tower":`Süs kulesi`,"Stack the Light piece far inland, six squares or more from any water: a stone tower with a belvedere on top for the view.":`Fener parçasını iç kesimlerde, herhangi bir sudan en az altı kare uzakta üst üste koy: tepesinde manzara için bir seyir köşkü olan taş bir kule.`,Temple:`Tapınak`,"Rest marble of five blocks or more on four or more pillars, each two or more blocks tall; or a smaller one on pillars up on a marble podium.":`En az beş bloklu bir mermeri, her biri en az iki blok yüksekliğinde en az dört sütunun üstüne oturt; ya da daha küçüğünü, mermer bir podyumun üstündeki sütunlara.`,Keep:`İç kale`,"Pile marble three or more blocks high on a base at least two squares by two.":`En az ikiye iki karelik bir tabanın üstüne en az üç blok yüksekliğinde mermer yığ.`,Gatehouse:`Kale kapısı`,"Put an arch over a path with marble on one side and marble or a wall on the other.":`Bir yolun üstüne kemer koy; bir yanında mermer, öbür yanında mermer ya da duvar olsun.`,"Grand steps":`Büyük merdiven`,"Pile marble in three or more rows, each row one block higher than the last and two or more squares wide.":`Mermeri en az üç sıra halinde yığ; her sıra bir öncekinden bir blok yüksek ve en az iki kare geniş olsun.`,"Quay wall":`Rıhtım duvarı`,"Lay marble along the shore, right at the water’s edge.":`Mermeri kıyı boyunca, tam suyun kenarına diz.`,"Plinth and statue":`Kaide ve heykel`,"Put one marble block on a plaza and leave its top empty: it carries a statue, a sundial or an urn.":`Bir meydana tek bir mermer blok koy ve üstünü boş bırak: üstünde bir heykel, bir güneş saati ya da bir vazo durur.`,Bandstand:`Müzik köşkü`,"Rest four marble blocks on four pillars two or more tall, standing on the ground: an open pavilion where a band plays. A square of four is an octagon; a row or a bent line, a garden shelter.":`Dört mermer bloğu, yerde duran ve en az iki blok yüksekliğinde dört sütunun üstüne oturt: bir bandonun çaldığı açık bir köşk. Dörtlü bir kare sekizgen olur; bir sıra ya da kırık bir çizgi, bir bahçe çardağı.`,Stoa:`Stoa`,"Rest a long marble roof, three or more times as long as it is wide and more than six blocks, on pillars beside a plaza: a market hall with one sloping roof.":`Boyu eninin en az üç katı olan ve altı bloktan büyük uzun bir mermer çatıyı bir meydanın yanında sütunların üstüne oturt: tek eğimli çatısıyla bir çarşı.`,"Obelisk or column":`Dikilitaş ya da sütun`,"Stack marble three or more blocks high on a single square of a plaza, with nothing touching it: an obelisk with a gilt tip, or, four or more high, sometimes a column with a statue.":`Bir meydanın tek bir karesine en az üç blok yüksekliğinde mermer yığ, hiçbir şey ona değmesin: ucu yaldızlı bir dikilitaş olur; en az dört blok yüksekse bazen üstünde heykel olan bir sütun.`,Podium:`Podyum`,"Build a marble platform two or more blocks high and give it a use: a temple on top, a broad stair up its side, or a plaza over a quarter of its top.":`En az iki blok yüksekliğinde mermer bir platform yap ve ona bir iş ver: üstünde bir tapınak, yanından yukarı çıkan geniş bir merdiven ya da üstünün dörtte birinde bir meydan.`,Theatre:`Tiyatro`,"Pile marble in rows of seats, each row one block higher and four or more wide, with nothing at the top, facing a plaza or open ground.":`Mermeri oturma sıraları halinde yığ: her sıra bir blok daha yüksek ve en az dört kare geniş olsun, tepesi boş kalsın, bir meydana ya da açık bir alana baksın.`,"Shops in the wall":`Duvardaki dükkânlar`,"Build a long marble wall two blocks tall beside a plaza or a path (not a castle): little arched shops and a fountain open in it.":`Bir meydanın ya da yolun yanına iki blok yüksekliğinde uzun bir mermer duvar yap (kale değil): içinde küçük kemerli dükkânlar ve bir çeşme açılır.`,"Stone bridge":`Taş köprü`,"Lay arches across water from bank to bank, six or fewer long.":`Suyun üstüne bir kıyıdan öbürüne, en fazla altı uzunluğunda kemerler diz.`,"Bridge shops":`Köprü dükkânları`,"Build houses on a bridge two or more wide whose deck is a street (a path on it or at its end), leaving room to pass: they become shops over the river.":`Üstü sokak olan (üstünde ya da ucunda yol olan), en az iki genişliğinde bir köprünün üstüne, geçecek yer bırakarak evler yap: nehrin üstünde dükkân olurlar.`,"Sky bridge":`Gök köprüsü`,"Join two houses with arches a storey or more off the ground, with both houses rising at least a storey above them.":`İki evi yerden en az bir kat yukarıda kemerlerle birleştir; iki ev de kemerlerin en az bir kat üstüne çıksın.`,Viaduct:`Viyadük`,"Line up arches on dry land, and stack a second row on top for tiers.":`Kuru toprağa kemerleri sırala; katlı olsun diye üstüne ikinci bir sıra koy.`,Gateway:`Kemerli kapı`,"Put an arch over a path.":`Bir yolun üstüne kemer koy.`,Loggia:`Kemerli balkon`,"Hang arches off the side of a house, a storey or more up, with nothing at the far end.":`Bir evin yanından, en az bir kat yukarıda kemerler uzat; uzak ucunda hiçbir şey olmasın.`,"Flying buttress":`Uçan payanda`,"Hang arches off a tower, marble or a chapel, with nothing at the far end and nothing on top.":`Bir kuleden, mermerden ya da şapelden kemerler uzat; uzak ucunda ve üstünde hiçbir şey olmasın.`,Pier:`Uzun iskele`,"Run a straight line of three or more docks out from the shore.":`Kıyıdan dışarı doğru en az üç iskeleyi düz bir sıra halinde uzat.`,"Dug river and barge":`Kazılmış nehir ve mavna`,"Dig a narrow channel in from the sea with Dig (Nature drawer; Shift-drag paints) and it fills as a river: put a dock on it and a barge comes. Dig all round a building for a moat.":`Kaz ile (Doğa çekmecesi; Shift ile sürükleyince boyar) denizden içeri dar bir kanal kaz; kanal nehir olarak dolar: üstüne bir iskele koy, bir mavna gelir. Hendek için bir binanın her yanını kaz.`,Quay:`Rıhtım`,"Lay four or more docks in a row along the shore.":`Kıyı boyunca en az dört iskeleyi yan yana diz.`,"Container port":`Konteyner limanı`,"Fill a big block of sea with docks along the shore, at least three deep and six long, with open water beyond it. It becomes a container port, with cranes, stacks of containers, an office and floodlights.":`Kıyı boyunca denizin büyük bir parçasını iskeleyle doldur: en az üç derinlikte, altı uzunlukta, önü açık su olsun. Vinçleri, konteyner yığınları, bir ofisi ve projektörleriyle bir konteyner limanına dönüşür.`,"Container cranes":`Konteyner vinçleri`,"A port up to nine docks long gets a medium crane; from ten long, a big gantry crane as well, and from fourteen, more of both. With no ship in, the big crane holds its boom up high.":`Dokuz iskeleye kadar uzunlukta bir liman orta boy bir vinç alır; ondan itibaren bir de büyük portal vinç, on dörtten itibaren ikisinden de daha fazlası. Limanda gemi yokken büyük vinç kolunu yukarıda tutar.`,Boardwalk:`Tahta yol`,"Lay a straight line of docks across a cove, with land at both ends.":`Bir koyun bir yanından öbürüne, iki ucu karada olan düz bir iskele sırası diz.`,Shipyard:`Tersane`,"Lay docks three wide and six or more long, straight out from the shore, with a warehouse or a barn by the land end. Shipwrights build a ship on the slip down the middle, a cog (or a galleon on a slip of eight or more), and launch it with the town looking on.":`Kıyıdan dümdüz denize doğru, üç genişlikte ve altı ya da daha uzun iskeleler döşe; kara ucunun yanında bir depo ya da ambar olsun. Gemi ustaları ortadaki kızakta bir gemi yapar: bir koka (kızak sekiz ya da daha uzunsa bir kalyon) ve kasaba seyrederken onu denize indirir.`,Warehouse:`Depo`,"Build a house of six or more blocks, two or more storeys tall, facing a dock across the harbour street: loading doors climb its wall to a hoist.":`Liman sokağının karşısındaki bir iskeleye bakan, en az altı bloklu, en az iki katlı bir ev yap: yükleme kapıları duvarı boyunca bir vince kadar tırmanır.`,"Boats and ships":`Tekneler ve gemiler`,"Build docks with open water beside them and boats come: a rowboat at a single dock, and the longer the quay, the bigger the ship that calls: a cog at about four docks in a row, a galley or a galleon at about seven.":`Yanında açık su olan iskeleler yap, tekneler gelir: tek bir iskeleye bir sandal; rıhtım uzadıkça uğrayan gemi de büyür: yan yana dört kadar iskeleye bir koka, yedi kadarına bir kadırga ya da kalyon.`,"Merchant cog":`Ticaret kokası`,"Lay about four docks in a row along the shore with open sea beside them: a round-bellied trading cog calls there.":`Kıyı boyunca, yanında açık deniz olan dört kadar iskeleyi yan yana diz: oraya tombul gövdeli bir ticaret kokası uğrar.`,"Wheat field":`Buğday tarlası`,"Lay four or more garden squares in one patch within two squares of a windmill.":`Bir yel değirmenine en fazla iki kare uzaklıkta, tek parça halinde en az dört bahçe karesi döşe.`,Park:`Park`,"Lay nine or more garden squares in one patch, away from water and windmills.":`Sudan ve yel değirmenlerinden uzakta, tek parça halinde en az dokuz bahçe karesi döşe.`,"Walled garden":`Duvarlı bahçe`,"Close in six or more squares of grass with walls on every side, and build nothing inside.":`En az altı karelik çimenliği her yandan duvarla çevir ve içine hiçbir şey yapma.`,Paddock:`Çitli çayır`,"Close in six or more squares of grass with fences on every side, and build nothing inside.":`En az altı karelik çimenliği her yandan çitle çevir ve içine hiçbir şey yapma.`,"Country lane":`Köy yolu`,"Run a path out of town across open grass: four or more squares of it more than three squares from any building or plaza get hedges, field gates and milestones instead of street lamps.":`Kasabanın dışına, açık çimenliğin üstünden bir yol uzat: yolun her binadan ve meydandan üç kareden fazla uzaktaki en az dört karesine sokak lambası yerine çalı çitler, tarla kapıları ve mil taşları gelir.`,"Back gardens":`Arka bahçeler`,"Fence in the grass behind a row of two or more houses: each house gets its own long back garden, with a fruit tree at the far end.":`En az iki evlik bir sıranın arkasındaki çimenliği çitle çevir: her evin, ucunda bir meyve ağacı olan kendi uzun arka bahçesi olur.`,"Village green":`Köy çayırı`,"Leave a patch of grass between two rows of houses that face each other across it, with a path beside it: it becomes the village green, with a maypole.":`Karşılıklı bakan iki sıra evin arasında, yanında bir yol olan bir çimenlik bırak: bahar direğiyle birlikte köy çayırı olur.`,Orchard:`Meyve bahçesi`,"Plant six or more trees in rows, two squares apart each way: they become an orchard, with ladders, baskets of apples and beehives.":`En az altı ağacı her yönde iki kare arayla sıralar halinde dik: el merdivenleri, elma sepetleri ve arı kovanlarıyla bir meyve bahçesi olur.`,"Pocket park":`Cep parkı`,"Leave a small patch of grass, two to sixteen squares, shut in by houses and paths.":`Evlerle ve yollarla çevrili, iki ila on altı karelik küçük bir çimenlik bırak.`,Churchyard:`Şapel bahçesi`,"Wall or fence in some garden or grass beside a chapel: it fills with headstones and a yew, with a roofed lychgate where a path goes through the wall.":`Bir şapelin yanındaki bahçeyi ya da çimenliği duvarla ya da çitle çevir: içi mezar taşları ve bir porsuk ağacıyla dolar; yolun duvardan geçtiği yerde çatılı bir giriş kapısı olur.`,"Herb garden":`Ot bahçesi`,"Lay garden in a yard closed in on every side by buildings or walls (a fence will not do).":`Her yanı binalarla ya da duvarlarla kapalı bir avluya bahçe döşe (çit olmaz).`,"Street lamps":`Sokak lambaları`,"Lay a path four or more squares long: lamps go up at its ends, its corners and along it.":`En az dört kare uzunluğunda bir yol döşe: uçlarına, köşelerine ve boyunca lambalar dikilir.`,"Laundry lines":`Çamaşır ipleri`,"Face two houses two or more storeys tall across a narrow gap of one to three squares; most such gaps get a washing line.":`En az iki katlı iki evi, bir ila üç karelik dar bir aralıkla karşı karşıya koy; böyle aralıkların çoğuna bir çamaşır ipi gerilir.`,Garrison:`Garnizon`,"Build a keep, or ring a yard with castle walls and a gatehouse or castle turret: a troop of soldiers marches round it.":`Bir iç kale yap ya da bir avluyu kale duvarlarıyla ve bir kale kapısı ya da kale burcuyla çevir: bir bölük asker çevresinde yürür.`,Rider:`Atlı`,"Every castle with a garrison keeps a rider, whose horse waits by the gate. Lay a path from the gate and the rider rides out along it, to the plaza if it reaches one.":`Garnizonu olan her kalenin bir atlısı vardır, atı kapının yanında bekler. Kapıdan bir yol döşe, atlı o yol boyunca dışarı çıkar; yol bir meydana varıyorsa meydana kadar gider.`,"Market cross":`Pazar taşı`,"Put a single marble block on a plaza with two or more stalls round it (and no fountain beside it): it becomes the market cross.":`Bir meydana, çevresinde en az iki tezgâh olan (ve yanında çeşme olmayan) tek bir mermer blok koy: pazar taşı olur.`,"Basketball court":`Basketbol sahası`,"Paint a field three by two, three by three or four by three: a basketball court with a hoop at each end. Residents come and play two or three a side.":`Üçe iki, üçe üç ya da dörde üç bir saha boya: her ucunda bir pota olan bir basketbol sahası. Sakinler gelip ikişer ya da üçer kişilik takımlarla oynar.`,"Tennis court":`Tenis kortu`,"Paint a field two wide and four to six long (or three wide and five or six long, for doubles): a tennis court with a net, clay or grass beside a garden. Residents come and play.":`Eni iki, boyu dört ila altı olan bir saha boya (çiftler için eni üç, boyu beş ya da altı): fileli bir tenis kortu, toprak ya da bir bahçenin yanındaysa çim. Sakinler gelip oynar.`,"Football pitch":`Futbol sahası`,"Paint a field four by six or bigger (three wide will do if it is seven long): a grass pitch with goals and corner flags. Residents come and play a few a side.":`Dörde altı ya da daha büyük bir saha boya (boyu yediyse eni üç de olur): kaleleri ve köşe bayraklarıyla çim bir saha. Sakinler gelip birkaç kişilik takımlarla oynar.`,"Bowling green":`Çim bowlingi`,"Paint a field four by four: a close-cut bowling green. Grown-ups come and roll bowls at the jack, slowly.":`Dörde dört bir saha boya: kısa biçilmiş bir çim bowling sahası. Büyükler gelip toplarını yavaş yavaş hedef topa doğru yuvarlar.`,"Croquet lawn":`Kroket çimi`,"Paint a field four by five: a croquet lawn with six hoops and a peg. Grown-ups come and knock their balls through the hoops in turn.":`Dörde beş bir saha boya: altı çemberli ve bir kazıklı bir kroket çimi. Büyükler gelip sırayla toplarını çemberlerden geçirir.`,"Boules court":`Petank sahası`,"Paint a field one wide and three or four long: a gravel boules court. Grown-ups come and toss their boules at the little jack.":`Eni bir, boyu üç ya da dört olan bir saha boya: çakıllı bir petank sahası. Büyükler gelip toplarını küçük hedef topa doğru atar.`,"Running track":`Koşu pisti`,"Paint a field one wide and five or more long (or two wide and seven or more): a running track. Children come and race.":`Eni bir, boyu en az beş (ya da eni iki, boyu en az yedi) olan bir saha boya: bir koşu pisti. Çocuklar gelip yarışır.`,"Kickabout green":`Mahalle sahası`,"Paint a small or odd-shaped patch of field (two by two, an L): a plain green with jumpers for goalposts. Children come and kick a ball about.":`Küçük ya da tuhaf biçimli bir saha parçası boya (ikiye iki, bir L): kale direği yerine kazakların konduğu sade bir çimen. Çocuklar gelip top koşturur.`,"Market day":`Pazar kuruluyor`,"Lay a plaza at least three by three with two stalls on it, and houses round it. On market mornings traders set up stalls there, a busker juggles and the town comes to buy, showing what they want in a picture bubble and paying with a coin, and a fisher's catch and an orchard's apples come to the stalls too.":`En az üçe üç, üstünde iki tezgâh olan bir meydan döşe, çevresine de evler. Pazar kurulan sabahlarda satıcılar orada tezgâh açar, bir sokak sanatçısı hokkabazlık yapar ve kasaba alışverişe gelir: herkes ne istediğini bir resimli balonla gösterir ve bir madeni parayla öder. Balıkçının avı ve meyve bahçesinin elmaları da tezgâhlara gelir.`,"Market days, from dawn to early afternoon":`Pazar kurulan günlerde, şafaktan öğleden sonranın başına kadar`,"A wedding":`Bir düğün`,"Put a chapel (a house beside a tower) with its door on a path that runs to a plaza no more than 20 steps away, and houses round about. Every few minutes by day the bells ring for a wedding: the party, dressed in black and white, lines the way from the door, and the couple lead a procession through the streets to the plaza in a shower of petals.":`Kapısı, en fazla 20 adım ötedeki bir meydana giden bir yola açılan bir şapel (bir kulenin yanında bir ev) koy, çevresine de evler. Gündüz birkaç dakikada bir düğün için çanlar çalar: siyah beyaz giyinmiş davetliler kapıdan çıkan yolun iki yanına dizilir, çift de taç yaprağı yağmuru altında sokaklardan meydana giden bir alayın başında yürür.`,"By day, every five to seven minutes":`Gündüz, beş ila yedi dakikada bir`,"A ship is launched":`Gemi denize iniyor`,"Build a shipyard with houses round about. When its ship is finished, bunting goes up along the slip, the town lines the decks and the shore, a bottle breaks on the bow, and the ship slides down into the sea with a great splash and sails away.":`Çevresinde evler olan bir tersane yap. Gemisi bitince kızak boyunca bayraklar asılır, kasaba iskelelere ve kıyıya dizilir, pruvada bir şişe kırılır ve gemi büyük bir şapırtıyla denize kayıp uzaklaşır.`,"By day, when a ship is finished":`Gündüz, bir gemi bitince`,"A raid":`Bir baskın`,"A town of 14 buildings or more with a shore a ship can reach is raided now and then by day: a longship runs up the beach (rowing boats where there is none), the band loots and sets fires, and the townsfolk fight back with brooms. Sink the ship with a bomb or lightning before it lands and they never come ashore; they only come by themselves when the Raiders switch in the menu is on.":`En az 14 binası ve bir geminin ulaşabileceği bir kıyısı olan kasaba, gündüz arada bir baskına uğrar: uzun bir gemi kumsala çıkar (kumsal yoksa kayıklar gelir), çete yağmalar ve ateşe verir, kasabalılar da süpürgelerle karşılık verir. Gemiyi karaya varmadan bir bomba ya da yıldırımla batırırsan hiç karaya çıkamazlar; kendiliğinden yalnızca menüdeki Yağmacılar düğmesi açıkken gelirler.`,"With Raiders on in the menu: after 8 minutes of play, then every 12 to 20; or the Raid tool any time":`Menüde Yağmacılar açıkken: oyunun 8. dakikasından sonra, ardından 12 ila 20 dakikada bir; ya da istediğin zaman Baskın aracıyla`,"The midwinter festival":`Kış ortası şenliği`,"Every town dresses up for the festival: strings of lights along the streets and round the squares, wreaths on the doors and a tree on the main square. It goes up house by house and lights up at dusk.":`Her kasaba şenlik için süslenir: sokaklar boyunca ve meydanların çevresinde ışık dizileri, kapılarda çelenkler ve ana meydanda bir ağaç. Süsler ev ev asılır ve akşam olunca yanar.`,"The last third of winter, lit from dusk":`Kışın son üçte biri, akşamdan itibaren ışıklı`,"A beach day":`Plaj günü`,"Build a town of eight houses or more within 40 steps of sand by the sea (the strip where flat land meets the water). Families carry parasols, deckchairs and pails down to it, swim, paddle and build sandcastles, an ice-cream cart comes with a queue, and rain sends them running home.":`Deniz kenarındaki kuma (düz karanın suyla buluştuğu şerit) en fazla 40 adım uzaklıkta, en az sekiz evli bir kasaba yap. Aileler oraya şemsiye, şezlong ve kova taşır; yüzer, sığ suda oynar ve kumdan kaleler yapar; bir dondurma arabası gelir ve önünde kuyruk olur; yağmur yağınca da koşa koşa eve dönerler.`,"Summer, fair weather, by day":`Yaz, güzel hava, gündüz`,Picnics:`Piknikler`,"Leave open grass with a few trees beside your houses. On fair spring days (and in summer, if the town has no beach) families carry out checked blankets and baskets, spread them on the grass and sit round them while the children chase about.":`Evlerinin yanında birkaç ağaçlı açık bir çimenlik bırak. Güzel ilkbahar günlerinde (kasabanın plajı yoksa yazın da) aileler kareli örtüler ve sepetler getirir, örtüleri çimene serip etrafında oturur, çocuklar da etrafta koşturup birbirini kovalar.`,"Spring (summer too, with no beach), fair weather, by day":`İlkbahar (plaj yoksa yaz da), güzel hava, gündüz`,"A snow day":`Kar günü`,"Lay a plaza with houses round it. When snow lies deep, the children come running out, roll a snowman in the middle of the square, give it a hat and a scarf, then build snow forts either side and have a snowball fight.":`Çevresinde evler olan bir meydan döşe. Kar kalın tutunca çocuklar koşarak dışarı çıkar, meydanın ortasında bir kardan adam yuvarlar, ona şapka ve atkı takar, sonra iki yana kardan kaleler yapıp kartopu savaşı yapar.`,"When snow lies deep, by day":`Kar kalın tutunca, gündüz`,"A harvest supper":`Hasat yemeği`,"Lay a plaza at least three by three with houses round it. In autumn, late in the day, the neighbours set a long table down the middle of the square under a string of lanterns and sit down to supper together.":`Çevresinde evler olan, en az üçe üç bir meydan döşe. Sonbaharda, günün geç saatlerinde komşular meydanın ortasına, bir dizi fenerin altına uzun bir masa kurar ve birlikte akşam yemeğine oturur.`,"Autumn, from late afternoon into dusk":`Sonbahar, ikindiden akşama kadar`,"Carol singers":`Kapı kapı şarkıcılar`,"Build six houses or more round the middle of town. At dusk a band of singers with lanterns goes from door to door singing, and whoever is at home comes out onto the step to listen.":`Kasabanın ortasının çevresine en az altı ev yap. Akşam, ellerinde fenerlerle bir grup şarkıcı kapı kapı dolaşıp şarkı söyler; evde kim varsa dinlemek için kapının önüne çıkar.`,"Winter or the festival, at dusk":`Kış ya da şenlik, akşam`,"The harvest":`Hasat`,"Grow a wheat field with a windmill that can be walked to. Farmhands mow it with scythes a square at a time, stooks stand on the stubble and the sheaves are carried to the mill for flour.":`Yürüyerek ulaşılabilen bir yel değirmeni olan bir buğday tarlası yetiştir. Tarım işçileri onu tırpanla kare kare biçer, anızın üstünde demet yığınları durur, demetler un olmak için değirmene taşınır.`,"Late summer and autumn, by day, when it is dry":`Yaz sonu ve sonbahar, gündüz, hava kuruyken`,"Ships unloading":`Yük boşaltan gemiler`,"Build a quay with shops, an inn or stalls within 24 steps of it. Ships come in and land crates, barrels and sacks, and carters wheel the goods up to the shops by handcart.":`24 adım içinde dükkânlar, bir han ya da tezgâhlar olan bir rıhtım yap. Gemiler gelip sandıkları, fıçıları ve çuvalları karaya çıkarır; hamallar da malları el arabasıyla dükkânlara götürür.`,"Whenever a ship is in, by day":`Limanda gemi olduğu her zaman, gündüz`,"Cargo ship":`Yük gemisi`,"Build a port ten or more docks long with open sea off it. A steel cargo ship stacked with containers comes in behind a little tug; the cranes lower their booms, unload some containers and load others, and it sails out again with the tug.":`Önü açık deniz olan, on ya da daha fazla iskele uzunluğunda bir liman yap. Konteynerlerle dolu çelik bir yük gemisi küçük bir römorkörün ardından gelir; vinçler kollarını indirir, bazı konteynerleri boşaltır, başkalarını yükler ve gemi römorkörle yeniden açılır.`,"Whenever its berth is free":`Rıhtımı her boşaldığında`,"Unloading the containers":`Konteynerler boşaltılıyor`,"Build a port with shops, an inn or stalls within 24 steps of it. A container from the ship is set down by the harbour office; dock workers in yellow jackets swing its doors open and carry out crates, barrels and sacks, and carters wheel them up to the shops.":`24 adım içinde dükkânlar, bir han ya da tezgâhlar olan bir liman yap. Gemiden bir konteyner liman ofisinin yanına indirilir; sarı yelekli liman işçileri kapılarını açıp sandıkları, fıçıları ve çuvalları dışarı taşır, arabacılar da onları dükkânlara götürür.`,"After a cargo ship has been in":`Bir yük gemisi uğradıktan sonra`,"Waving a ship in":`Gemiye el sallamak`,"Build a pier or a quay where ships call. When a big ship comes in, the children run to the end of the pier nearest it and wave, jump and cheer it in to its berth.":`Gemilerin uğradığı bir uzun iskele ya da rıhtım yap. Büyük bir gemi geldiğinde çocuklar ona en yakın iskelenin ucuna koşar, gemi yanaşana kadar el sallar, zıplar ve tezahürat yapar.`,"When a big ship comes in, by day":`Büyük bir gemi geldiğinde, gündüz`,"The catch comes in":`Av geliyor`,"Put a pier with a fish stall or a fish shop within 20 steps of it. The fisher carries baskets of the catch up to the stall (on market days, to the market), and people come down to buy a fish, asking with a fish in their speech bubble and paying with a coin.":`20 adım içinde bir balık tezgâhı ya da balıkçı dükkânı olan bir uzun iskele koy. Balıkçı sepet sepet avı tezgâha taşır (pazar günleri pazara), insanlar da balık almaya iner: konuşma balonlarında bir balıkla isterler ve bir madeni parayla öderler.`,"Dawn and by day":`Şafak ve gündüz`,"Bread from the mill":`Değirmenden ekmek`,"Have a windmill and a bakery (a shop, else the inn) the miller can walk between. The miller carries sacks of flour to the bakery, the baker carries trays of loaves to the stalls and cafés, and people come for bread in the morning.":`Değirmencinin arasında yürüyebileceği bir yel değirmenin ve bir fırının (bir dükkân, yoksa han) olsun. Değirmenci fırına un çuvalları taşır, fırıncı tezgâhlara ve kafelere tepsi tepsi somun götürür, insanlar da sabah ekmek almaya gelir.`,"Apples to market":`Elmalar pazara`,"Plant an orchard with a market stall or a shop within 24 steps of it. At harvest the pickers fill the big baskets, the gardener carries a basket heaped with apples to the stall, and people come to buy one, asking with an apple in their speech bubble.":`24 adım içinde bir pazar tezgâhı ya da dükkân olan bir meyve bahçesi dik. Hasatta toplayıcılar büyük sepetleri doldurur, bahçıvan tepeleme elma dolu bir sepeti tezgâha taşır, insanlar da konuşma balonlarında bir elmayla gelip bir tane alır.`,"At harvest time, by day":`Hasat zamanı, gündüz`,"Fetching water":`Su taşıma`,"Put a well or a fountain near houses. Now and then somebody comes with a pail, fills it and carries the water home on a yoke.":`Evlerin yakınına bir kuyu ya da çeşme koy. Arada bir biri kovayla gelir, kovayı doldurur ve suyu omuz sırığıyla eve taşır.`,"By day":`Gündüz`,"Washing day":`Çamaşır günü`,"Hang a laundry line between two houses. The washing is carried out in a basket and hung up in the morning, and taken in again at dusk or when it rains.":`İki evin arasına bir çamaşır ipi ger. Çamaşırlar sabah sepetle dışarı taşınıp asılır, akşam ya da yağmur yağınca yeniden toplanır.`,"Mornings; taken in at dusk or in the rain":`Sabahları; akşam ya da yağmurda toplanır`,"School and hopscotch":`Okul ve seksek`,"Build a schoolhouse with families living near it. The teacher calls the children in for their lesson, and afterwards they burst out to hop the hopscotch in the yard.":`Yakınında aileler oturan bir okul yap. Öğretmen çocukları derse çağırır, ders bitince de çocuklar avluda seksek oynamaya fırlar.`,"By day, a lesson every two and a half minutes":`Gündüz, iki buçuk dakikada bir ders`,"The smith at work":`Demirci iş başında`,"Build a smithy. The smith hammers at the anvil with sparks flying, then works the forge inside, and the forge chimney smokes while it is hot.":`Bir demirhane yap. Demirci kıvılcımlar saçarak örse çekiç vurur, sonra içeride ocakta çalışır; ocak sıcakken bacası tüter.`,"A show":`Bir gösteri`,"Build a bandstand or a theatre with houses round about. A band or players perform for a minute while people come to sit or stand round and clap.":`Çevresinde evler olan bir müzik köşkü ya da tiyatro yap. Bir bando ya da oyuncular bir dakika gösteri yapar, insanlar da gelip çevresinde oturur ya da ayakta durup alkışlar.`,"By day and at dusk, every three and a half minutes":`Gündüz ve akşam, üç buçuk dakikada bir`,"Games on the field":`Sahada oyunlar`,"Lay a playing field near houses: its shape decides the game (basketball, tennis, football, bowls, boules, croquet or races). People come out to play and others stop at the edge to watch and clap.":`Evlerin yakınına bir oyun sahası döşe: oyunu şekli belirler (basketbol, tenis, futbol, çim bowlingi, petank, kroket ya da koşu). İnsanlar oynamaya çıkar, başkaları da kenarda durup izler ve alkışlar.`,"By day and into dusk, a game every minute or so":`Gündüz ve akşama kadar, aşağı yukarı dakikada bir oyun`,Dogs:`Köpekler`,"Build six houses or more: every sixth house keeps a dog. It trots at its people’s heels, says hello to passers-by and chases the cats.":`En az altı ev yap: her altıncı evin bir köpeği olur. Sahiplerinin peşinden tırıs tırıs gider, gelip geçenlere merhaba der ve kedileri kovalar.`,"All day":`Bütün gün`,Bikes:`Bisikletler`,"Build a street of houses: some front doors have a bike leaning by them. For a long trip its owner rides it, carries small shopping in the basket, and leans it by the door they stop at.":`Evlerden bir sokak yap: bazı ön kapıların yanında bir bisiklet durur. Sahibi uzun bir yol için ona biner, küçük alışverişini sepete koyar ve durduğu kapının yanına yaslar.`,"By day and at dusk, in fair weather":`Gündüz ve alacakaranlıkta, güzel havada`,"A scuffle":`Bir itişme`,"Any town with people out in its streets: now and then two who bump into each other vanish into a dust cloud of fists and stars while a crowd gathers. They sit up dazed and dust themselves off, and the watchman or a guard breaks it up if one is near.":`Sokaklarında insan olan her kasabada: arada bir, birbirine çarpan iki kişi yumruklardan ve yıldızlardan oluşan bir toz bulutunun içinde kaybolur, bu sırada bir kalabalık toplanır. Sersemlemiş halde doğrulup üstlerini silkelerler; yakında bekçi ya da bir muhafız varsa kavgayı ayırır.`,"Now and then, when two walkers bump into each other":`Arada bir, yürüyen iki kişi birbirine çarptığında`,"The lamplighter":`Lambacı`,"Put street lamps along your paths. At dusk the lamplighter walks the round with a pole and lights them one by one, while the windows light up as people come home.":`Yollarının kenarına sokak lambaları koy. Akşam lambacı elinde bir sırıkla turunu atar ve lambaları tek tek yakar; insanlar eve döndükçe pencereler de aydınlanır.`,"At dusk":`Akşam`,"The night watch":`Gece bekçisi`,"Build a town of 12 houses or more with no castle. At night the watchman walks a round of its streets and squares with a lantern on a pole, stopping to look about at each.":`Kalesi olmayan, en az 12 evli bir kasaba yap. Geceleyin bekçi, sırığın ucunda bir fenerle kasabanın sokaklarında ve meydanlarında tur atar, her birinde durup etrafa bakar.`,"At night":`Gece`,"The fire brigade":`İtfaiye`,"Set a building alight with Lightning or a bomb in a town with a well or a fountain. The brigade wheels the pump cart from it and hoses the fire while neighbours pass buckets, and afterwards crews put the burnt buildings back up under scaffolding.":`Kuyusu ya da çeşmesi olan bir kasabada bir binayı Yıldırım ya da bir bombayla tutuştur. İtfaiye pompa arabasını oradan sürüp getirir ve yangını hortumla söndürür, komşular da elden ele kova taşır; sonra ekipler yanan binaları yapı iskelesi altında yeniden kurar.`,"As soon as something catches fire":`Bir şey tutuşur tutuşmaz`,"Loaves delivered":`Dağıtılan somun`,"Fish landed":`Karaya çıkan balık`,Weddings:`Düğünler`,"Times nuked":`Nükleer patlama`,"Bombs dropped":`Atılan bomba`,"Lightning strikes":`Düşen yıldırım`,"Fires started":`Çıkan yangın`,"Buildings ruined":`Yıkılan bina`,Scuffles:`İtişmeler`,"Raids survived":`Atlatılan baskın`,"On fire right now":`Şu an yanan`,Harbour:`Liman`,"Blue roof, boarded walls, a glazed door":`Mavi çatı, tahta kaplı duvarlar, camlı bir kapı`,Thatch:`Saz çatı`,"A straw roof and green shutters":`Saman bir çatı ve yeşil panjurlar`,Tudor:`Tudor`,"Red tiles over half-timbered walls":`Yarı ahşap duvarların üstünde kırmızı kiremitler`,"Slate roof, tall windows, bands between the storeys":`Arduvaz çatı, uzun pencereler, katlar arasında şeritler`,Farm:`Çiftlik`,"Green roof, timbered gables, boarded upper storeys":`Yeşil çatı, ahşap çatı alınlıkları, tahta kaplı üst katlar`,Villa:`Villa`,"Orange tiles and round-topped windows":`Turuncu kiremitler ve üstü yuvarlak pencereler`,Plains:`Ova`,Hills:`Tepeler`,Mountain:`Dağ`,"River valley":`Nehir vadisi`,Islands:`Adalar`,"Harbour town":`Liman kasabası`,"Marble city":`Mermer şehir`,"Castle town":`Kale kasabası`,"Market town":`Pazar kasabası`,"River town":`Nehir kasabası`,"Farming village":`Çiftçi köyü`,"Hill town":`Tepe kasabası`,"Garden town":`Bahçe kasabası`,"Built {got} / {all}":`Yapılan {got} / {all}`,"You have built this":`Bunu yaptın`,"you have built this":`bunu yaptın`,"New building unlocked!":`Yeni bina açıldı!`,"New building unlocked: {name}. Open it in the almanac":`Yeni bina açıldı: {name}. Almanakta aç`,"tap to place":`yerleştirmek için dokun`,"left click to place":`yerleştirmek için sol tıkla`,"right click to remove":`kaldırmak için sağ tıkla`,"tap to undo":`geri almak için dokun`};export{e as default};